3	import jakarta.validation.Constraint;
4	import jakarta.validation.Payload;
5	import java.lang.annotation.*;
6	
7	/**
8	 * Validates that a telephone value can be converted to canonical E.164 form (a leading
9	 * {@code '+'} followed by 8 to 15 digits), assuming the {@code '+61'} country code when the
10	 * value carries no explicit one.
11	 */
12	@Target({ ElementType.FIELD })
13	@Retention(RetentionPolicy.RUNTIME)
14	@Constraint(validatedBy = TelephoneDigitsValidator.class)
15	@Documented
16	public @interface TelephoneDigits {
17	
18	    String message() default "Telephone must be a valid E.164 number (8 to 15 digits after the country code)";
19	
20	    Class<?>[] groups() default {};
21	
22	    Class<? extends Payload>[] payload() default {};
23	}
