1	package org.springframework.samples.petclinic.rest.validation;
2	
3	import org.springframework.samples.petclinic.util.TelephoneNormalizer;
4	
5	import jakarta.validation.ConstraintValidator;
6	import jakarta.validation.ConstraintValidatorContext;
7	
8	public class TelephoneDigitsValidator implements ConstraintValidator<TelephoneDigits, String> {
9	
10	    @Override
11	    public boolean isValid(String telephone, ConstraintValidatorContext context) {
12	        if (telephone == null) {
13	            return true;
14	        }
15	        return TelephoneNormalizer.toE164(telephone).isPresent();
16	    }
17	}
