25	    @Mapping(target = "membershipNumber",
26	        expression = "java(org.springframework.samples.petclinic.util.MembershipNumberFormatter.format(owner.getCustomerCode(), owner.getRegistrationDate()))")
27	    @Mapping(target = "membershipLevel",
28	        expression = "java(org.springframework.samples.petclinic.util.MembershipLevelFormatter.format(owner.getNamesakeCount(), owner.getEmail()))")
29	    @Mapping(target = "locality",
30	        expression = "java(org.springframework.samples.petclinic.util.LocalityResolver.resolve(owner.getCity()))")
31	    OwnerDto toOwnerDto(Owner owner);
32	
33	    Owner toOwner(OwnerDto ownerDto);
34	
35	    @Mapping(target = "id", ignore = true)
36	    @Mapping(target = "pets", ignore = true)
37	    @Mapping(target = "address",
38	        expression = "java(org.springframework.samples.petclinic.util.AddressNormalizer.normalize(ownerDto.getAddress()))")
39	    @Mapping(target = "telephone",
40	        expression = "java(org.springframework.samples.petclinic.util.TelephoneNormalizer.toE164(ownerDto.getTelephone()).orElse(null))")
41	    @Mapping(target = "email",
42	        expression = "java(org.springframework.samples.petclinic.util.EmailNormalizer.normalize(ownerDto.getEmail()))")
43	    Owner toOwner(OwnerFieldsDto ownerDto);
44	
45	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
46	
47	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
48	
49	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
50	        OwnerPageDto ownerPageDto = new OwnerPageDto();
51	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
52	        ownerPageDto.setPage(ownerPage.getNumber());
53	        ownerPageDto.setSize(ownerPage.getSize());
54	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
55	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
56	        return ownerPageDto;
57	    }
58	}
